-- ============================================================================
-- QI ASSOCIATE DEEP SEED: Quantitative Interpretation, beginner tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, and the question rows from the
-- committed bank JSONs under tools/course-banks/qi/beginner.
--
-- What this tier owns: FEASIBILITY. What a QI study asks, the Ekene field and
-- the teaching pack, units and polarity; the data inventory and the usability
-- matrix; seismic QC (the amplitude spectrum, band edges and the centroid,
-- signal to noise from coherency, footprint); measured shear against
-- Greenberg-Castagna, the local shear trend and its prediction interval, the
-- elastic set; the fluids, oil-to-brine substitution, the wet trend and the
-- distance from it; modelled AVO and the feasibility verdict.
--
-- AN APP COURSE. The Suite app is QI Studio; the practicals also run in the
-- course's own explorer panels. The tier's capstone grades six values on a
-- held-out synthetic case, each a return value of a vendored engine. No BEGIN
-- or COMMIT: apply_qi.sh wraps this file in one transaction.
-- ============================================================================

values ('qi', 'beginner', '{"modules":[{"key":"m01-what-a-qi-study-asks","title":"What a QI Study Asks","lesson_keys":["l01-why-a-qi-study","l02-the-ekene-field-and-the-teaching-pack","l03-the-two-questions","l04-times-polarity-and-impedance-units","l05-the-panels-and-their-refusals"]},{"key":"m02-the-data-inventory","title":"The Data Inventory","lesson_keys":["l01-what-a-qi-study-needs-from-each-well","l02-the-usability-matrix","l03-limited-and-missing-curves","l04-the-issue-register"]},{"key":"m03-seismic-qc","title":"Seismic QC","lesson_keys":["l01-the-amplitude-spectrum","l02-band-edges-and-the-centroid","l03-signal-to-noise-from-trace-coherency","l04-acquisition-footprint"]},{"key":"m04-elastic-logs-at-the-wells","title":"Elastic Logs at the Wells","lesson_keys":["l01-what-rock-physics-hands-to-qi","l02-measured-shear-against-greenberg-castagna","l03-the-local-shear-trend-and-its-interval","l04-the-elastic-set"]},{"key":"m05-will-the-fluid-show","title":"Will the Fluid Show?","lesson_keys":["l01-the-fluids-at-ekene-conditions","l02-oil-to-brine-substitution-on-a-log","l03-how-far-impedance-and-vpvs-move","l04-the-wet-trend-on-a-crossplot","l05-distance-from-the-wet-trend"]},{"key":"m06-the-feasibility-verdict","title":"The Feasibility Verdict","lesson_keys":["l01-modelled-avo-at-the-zone-top","l02-in-situ-against-brine","l03-writing-the-verdict","l04-the-capstone-brief"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
      updated_at = now();

delete from public.academy_quiz_questions
 where app_slug = 'qi' and tier = 'beginner';

